		scanf ("%lld %lld %lld", &n, &k, &g);

		long long stolen = min((g - 1) / 2 * n, k * g);
		long long rest = (k * g - stolen) % g;

		if (rest > 0) {
		    stolen -= (g - 1) / 2;
		    long long last = ((g - 1) / 2 + rest) % g;

		    if (last * 2 < g) {
		        stolen += last;
		    } else {
		        stolen -= g - last;
		    }
		}

		printf ("%lld\n", stolen);
	}
}

